import React, { useState, useEffect } from 'react';
import axios from 'react';

export default function TeacherContent({ userName, teachingSubject, materials, fetchData, timetable, preSelectedGrade, setPreSelectedGrade, teacherGrades }) {
  const [formTitle, setFormTitle] = useState('');
  const [formType, setFormType] = useState('PDF'); 
  const [formFilePath, setFormFilePath] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [formGrade, setFormGrade] = useState(teacherGrades[0] || 'Grade 8');
  const [tableFilter, setTableFilter] = useState('All');

  useEffect(() => {
    if (preSelectedGrade) {
      setFormGrade(preSelectedGrade);
      setTableFilter(preSelectedGrade); 
      setPreSelectedGrade(null);
    } else if (teacherGrades.length > 0 && !formGrade) {
      setFormGrade(teacherGrades[0]);
    }
  }, [preSelectedGrade, teacherGrades, formGrade, setPreSelectedGrade]);

  const getYoutubeId = (url) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const getCorrectAccessUrl = (filePath) => {
    if (!filePath) return '#';
    if (filePath.startsWith('http://') || filePath.startsWith('https://')) {
      return filePath;
    }
    return `http://localhost:8082/${filePath}`;
  };

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', formTitle);
    formData.append('material_type', formType);
    formData.append('grade', formGrade);
    formData.append('subject', teachingSubject);
    formData.append('teacher_name', userName);

    if ((formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video') && selectedFile) {
        formData.append('file', selectedFile); 
    } else {
        formData.append('file_path', formFilePath);
    }

    axios.post('http://localhost:8082/api/add-material', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
    }).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ ${formType} Published Successfully!`);
        fetchData(); 
        setFormTitle(''); 
        setFormFilePath(''); 
        setSelectedFile(null);
      }
    }).catch(err => console.log(err));
  };

  const handleDeleteMaterial = (id) => {
    if (window.confirm("Are you sure you want to delete this resource?")) {
      axios.delete(`http://localhost:8082/api/delete-material/${id}`)
        .then(res => {
          if (res.data.status === "Success") {
            alert("🗑️ Material removed successfully!");
            fetchData();
          }
        }).catch(err => console.log(err));
    }
  };

  const filteredMaterials = materials.filter(m => {
    const subjectMatch = m.subject === teachingSubject;
    const gradeMatch = tableFilter === 'All' ? true : m.grade === tableFilter;
    return subjectMatch && gradeMatch;
  });

  // 🟢 FIXED SORTING LOGIC: අලුතින්ම ඇඩ් කරන ඒවා හැමතිස්සෙම වගුවේ උඩින්ම (Latest First) පෙන්වයි
  const courseLessons = filteredMaterials
    .filter(m => m.material_type !== 'Past Paper')
    .sort((a, b) => b.id - a.id); 

  const pastPapers = filteredMaterials
    .filter(m => m.material_type === 'Past Paper')
    .sort((a, b) => b.id - a.id); 

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '30px', fontFamily: 'sans-serif' }}>
      
      {/* Upload Portal Form */}
      <div>
        <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '22px' }}>Distributed Content Gateway ({teachingSubject})</h2>
        <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', borderLeft: '5px solid #145c2e', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }}>
          <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <input 
              type="text" 
              placeholder="Material Title (e.g., Lesson 01 - Core Matrix Structures)" 
              value={formTitle} 
              onChange={e => setFormTitle(e.target.value)} 
              required 
              style={styles.fullInput} 
            />
            
            <div style={{ display: 'flex', gap: '20px' }}>
              <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.fullInput}>
                {teacherGrades.length > 0 ? (
                  teacherGrades.map(g => <option key={g} value={g}>{g}</option>)
                ) : (
                  ['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12'].map(g => <option key={g} value={g}>{g}</option>)
                )}
              </select>

              <select value={formType} onChange={e => { setFormType(e.target.value); setSelectedFile(null); setFormFilePath(''); }} style={styles.fullInput}>
                <option value="PDF">📚 PDF Handout Documents</option>
                <option value="Past Paper">🎯 Official Past Exam Papers</option>
                <option value="Direct Video">📁 Direct Video Upload (MP4)</option>
                <option value="YouTube">🎬 YouTube Video Lesson</option>
                <option value="Zoom Link">🎥 Live Zoom Meeting Link</option>
                <option value="Recording">📼 Recorded Video / Drive Link</option>
              </select>
            </div>

            {formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video' ? (
              <input 
                type="file" 
                accept={formType === 'Direct Video' ? "video/mp4,video/*" : ".pdf"} 
                onChange={e => setSelectedFile(e.target.files[0])} 
                required 
                style={styles.fileInput} 
              />
            ) : (
              <input 
                type="text" 
                placeholder={
                  formType === 'YouTube' ? "Enter YouTube Video URL..." :
                  formType === 'Zoom Link' ? "Enter Live Zoom Meeting Link..." :
                  "Enter Google Drive or Cloud Recording Link..."
                } 
                value={formFilePath} 
                onChange={e => setFormFilePath(e.target.value)} 
                required 
                style={styles.fullInput} 
              />
            )}
            
            <button type="submit" style={styles.publishBtn}>Publish Material Content 🚀</button>
          </form>
        </div>
      </div>

      {/* GLOBAL RESOURCE CONTROLLER FILTER CONTAINER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: 'white', padding: '15px 25px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
        <h3 style={{ margin: 0, color: '#145c2e', fontSize: '16px', fontWeight: 'bold' }}>Active Dashboard Filter Scope</h3>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#475569' }}>Filter by Instance Grade:</span>
          <select 
            value={tableFilter} 
            onChange={e => setTableFilter(e.target.value)} 
            style={styles.filterDropdown}
          >
            <option value="All">🌐 All Assigned Grades</option>
            {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>
      </div>

      {/* SECTION 1: MAIN COURSE LESSON MODULES */}
      <div>
        <h3 style={{ margin: '0 0 12px 0', color: '#1e293b', fontSize: '17px', fontWeight: 'bold' }}>
          📚 Academic Coursework & Video Lesson Modules
        </h3>
        <div style={styles.tableWrapper}>
          <table style={styles.mainTable}>
            <thead>
              <tr style={styles.tableHeaderRow}>
                <th style={{ width: '50px', paddingLeft: '15px' }}>No.</th>
                <th style={{ width: '160px' }}>Media Preview</th> {/* 🟢 Player එකට ඉඩ මදි නොවෙන්න පළල වැඩි කළා */}
                <th>Course Content Title</th>
                <th style={{ width: '100px' }}>Grade</th>
                <th style={{ width: '150px' }}>Resource Type</th>
                <th style={{ width: '140px' }}>Access Node</th>
                <th style={{ width: '80px', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {courseLessons.length > 0 ? (
                courseLessons.map((m, index) => {
                  const ytId = getYoutubeId(m.file_path);
                  const actualType = m.material_type || 'Resource';
                  return (
                    <tr key={m.id || index} style={styles.tableBodyRow}>
                      <td style={{ fontWeight: 'bold', color: '#64748b', paddingLeft: '15px' }}>{index + 1}</td>
                      <td>
                        {/* 🟢 FIXED: YouTube ලින්ක් එකක් නම් කෙලින්ම වගුව ඇතුළේ ලයිව් ප්ලේයර් එකක් පෙන්වයි */}
                        {actualType === 'YouTube' && ytId ? (
                          <div style={{ borderRadius: '6px', overflow: 'hidden', width: '140px', height: '80px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' }}>
                            <iframe
                              width="100%"
                              height="100%"
                              src={`https://www.youtube.com/embed/${ytId}`}
                              title="YouTube Video"
                              frameBorder="0"
                              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                              allowFullScreen
                            ></iframe>
                          </div>
                        ) : (
                          <div style={styles.previewBox}>
                            <div style={styles.fallbackBadge(actualType)}>
                              {actualType === 'Direct Video' ? '🎥 MP4' : actualType === 'Zoom Link' ? '🎥 LIVE' : '📄 HANDOUT'}
                            </div>
                          </div>
                        )}
                      </td>
                      <td style={{ fontWeight: '600', color: '#1e293b' }}>{m.title}</td>
                      <td><span style={styles.gradeBadge}>{m.grade}</span></td>
                      <td><span style={styles.typeBadge(actualType)}>{actualType}</span></td>
                      <td>
                        <a href={getCorrectAccessUrl(m.file_path)} target="_blank" rel="noreferrer" style={styles.openLinkBtn}>Launch Resource ➔</a>
                      </td>
                      <td style={{ textAlign: 'center' }}>
                        <button onClick={() => handleDeleteMaterial(m.id)} style={styles.deleteMiniBtn}>Delete</button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr><td colSpan="7" style={styles.emptyRowStyle}>No course lesson modules deployed under this criteria.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* SECTION 2: SEPARATED PAST PAPERS ARCHIVE SECTION */}
      <div>
        <h3 style={{ margin: '0 0 12px 0', color: '#1e293b', fontSize: '17px', fontWeight: 'bold' }}>
          🎯 Official Past Examination Papers Archive
        </h3>
        <div style={styles.tableWrapper}>
          <table style={styles.mainTable}>
            <thead>
              <tr style={styles.tableHeaderRow}>
                <th style={{ width: '50px', paddingLeft: '15px' }}>No.</th>
                <th style={{ width: '160px' }}>Document Preview</th>
                <th>Examination Paper Title</th>
                <th style={{ width: '100px' }}>Grade</th>
                <th style={{ width: '150px' }}>Resource Type</th>
                <th style={{ width: '140px' }}>Access Node</th>
                <th style={{ width: '80px', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {pastPapers.length > 0 ? (
                pastPapers.map((m, index) => (
                  <tr key={m.id || index} style={styles.tableBodyRow}>
                    <td style={{ fontWeight: 'bold', color: '#64748b', paddingLeft: '15px' }}>{index + 1}</td>
                    <td>
                      <div style={styles.previewBox}>
                        <div style={styles.fallbackBadge('Past Paper')}>📝 EXAM PDF</div>
                      </div>
                    </td>
                    <td style={{ fontWeight: '600', color: '#b91c1c' }}>{m.title}</td>
                    <td><span style={styles.gradeBadge}>{m.grade}</span></td>
                    <td><span style={styles.typeBadge('Past Paper')}>Past Paper</span></td>
                    <td>
                      <a href={getCorrectAccessUrl(m.file_path)} target="_blank" rel="noreferrer" style={{ ...styles.openLinkBtn, color: '#b91c1c', backgroundColor: '#fef2f2', borderColor: '#fca5a5' }}>View Paper ➔</a>
                    </td>
                    <td style={{ textAlign: 'center' }}>
                      <button onClick={() => handleDeleteMaterial(m.id)} style={styles.deleteMiniBtn}>Delete</button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr><td colSpan="7" style={styles.emptyRowStyle}>No official past examination papers archived under this criteria.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

const styles = {
  fullInput: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '13.5px' },
  fileInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '13.5px' },
  publishBtn: { padding: '13px', backgroundColor: '#145c2e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', width: '100%', marginTop: '5px', boxShadow: '0 4px 10px rgba(20,92,46,0.1)' },
  filterDropdown: { padding: '8px 14px', borderRadius: '8px', border: '1px solid #145c2e', backgroundColor: 'white', fontSize: '13px', fontWeight: 'bold', color: '#145c2e', outline: 'none', cursor: 'pointer' },
  tableWrapper: { backgroundColor: 'white', padding: '20px', borderRadius: '15px', border: '1px solid #e2e8f0', overflowX: 'auto' },
  mainTable: { width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '800px' },
  tableHeaderRow: { borderBottom: '2px solid #f1f5f9', color: '#64748b', fontSize: '12.5px', height: '40px' },
  tableBodyRow: { borderBottom: '1px solid #f8fafc', height: '95px', fontSize: '13.5px' }, // 🟢 Player එකට ඉඩ ලැබෙන්න Row Height එක වැඩි කළා
